def f(x):
    return x ** 3

print(f(1), f(1.5), f(2))   # 1 3.375 8

def f(x):
    return x ** 3

def f_slope(x):
    return 3 * x ** 2

a = 1.0
def first_order(x):
    return f(a) + f_slope(a) * (x - a)

print(first_order(1.5))   # 2.5

def f_slope(x):
    return 3 * x ** 2

def f_curvature(x):
    return 6 * x

for x in [0.6, 1.0, 1.4]:
    print(x, round(f_slope(x), 2))   # 0.6 1.08 / 1.0 3.0 / 1.4 5.88
print(f_curvature(1.0))   # 6.0
